create or replace function public.create_initial_workspace(org_name text, farm_name text) returns uuid language plpgsql security definer set search_path=public as $$ declare new_org uuid; begin if auth.uid() is null then raise exception 'not authenticated'; end if; if length(trim(org_name)) < 2 or length(trim(farm_name)) < 2 then raise exception 'company and farm names are required'; end if; insert into public.organizations(name,slug) values (trim(org_name), lower(regexp_replace(trim(org_name),'[^a-zA-Z0-9]+','-','g'))||'-'||substr(auth.uid()::text,1,6)) returning id into new_org; insert into public.organization_members(organization_id,user_id,role,status) values (new_org,auth.uid(),'owner','active'); insert into public.farms(organization_id,name) values (new_org,trim(farm_name)); return new_org; end; $$;
revoke all on function public.create_initial_workspace(text,text) from public;
grant execute on function public.create_initial_workspace(text,text) to authenticated;
